# -*- coding: utf-8 -*-
import sys,json,hashlib
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]));sys.path.insert(0,str(Path(__file__).resolve().parent))
from gongbi_training.runtime import configure,LAB
configure()
import numpy as np,torch
from PIL import Image,ImageDraw,ImageFont
from gongbi_training.cunfa_probability_checks import conditional_role_check
from cunfa_retention_train_20261112 import retain_loss
ROOT=LAB/'cunfa_retention_v4_20261112';PREV=LAB/'cunfa_band_checked_20261112';TEACHER=LAB/'cunfa_roles_v2_20261112'
def read(p):return json.loads(Path(p).read_text('utf8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 result=read(ROOT/'results.json');protocol=result['protocol'];ds=read(PREV/'dataset_manifest.json');assert sha(PREV/'dataset_manifest.json')==protocol['reference_dataset_sha256'];assert sha(PREV/'foreground_refiner.pt')==protocol['initial_refiner_sha256'];assert sha(TEACHER/'flat_roles.pt')==protocol['teacher_sha256'];assert sha(Path(__file__).with_name('cunfa_retention_train_20261112.py'))==protocol['script_sha256'];assert all(sha(ROOT/(k+'.pt'))==v for k,v in result['checkpoint_hashes'].items());(ROOT/'references').mkdir(exist_ok=True);font=lambda n:ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',n);col=np.array([[234,239,226],[192,128,40],[40,135,180]],'uint8');records=[]
 for r in ds['records']:
  z=np.load(r['path']);assert sha(r['path'])==r['sha256'];image=z['image'];row=next(q for q in result['records'] if q['id']==r['id']);probs={};preds={}
  for name in ['v2_frozen','previous_refiner','matched_continuation','known_ink_retention']:
   p=np.load(ROOT/'predictions'/(r['id']+'_'+name+'.npz'))['prediction'];preds[name]=p;Image.fromarray(col[p]).save(ROOT/'predictions'/(r['id']+'_'+name+'.png'));probs[name]='predictions/'+r['id']+'_'+name+'.png'
  Image.fromarray(image).save(ROOT/'references'/(r['id']+'_input.png'));Image.open(PREV/'references'/(r['id']+'_overlay.png')).save(ROOT/'references'/(r['id']+'_overlay.png'))
  t=z['core_targets'];old=preds['v2_frozen'];prior=preds['previous_refiner'];new=preds['known_ink_retention'];dropped=(t!=255)&(t>0)&(old>0)&(prior==0);found=dropped&(new>0);remaining=dropped&(new==0);extra=(t!=255)&(t>0)&(prior>0)&(new==0);diff=image.copy();diff[found]=[30,165,75];diff[remaining]=[215,45,45];diff[extra]=[170,60,200];Image.fromarray(diff).save(ROOT/'predictions'/(r['id']+'_changes.png'))
  board=Image.new('RGB',(1200,450),'#f4f1e8');d=ImageDraw.Draw(board)
  for j,(im,title) in enumerate([(Image.fromarray(image),'原图'),(Image.fromarray(col[prior]),'上一轮范围修正'),(Image.fromarray(col[new]),'本轮：保留已有墨迹')]):
   im.thumbnail((385,335));board.paste(im,(j*400+6,40));d.text((j*400+6,8),title,font=font(21),fill='#243e32')
  d.text((8,395),'原始角色图：橙=结构，蓝=皴笔；未用参考遮罩修饰，仍不是完整笔触。',font=font(19),fill='#815238');board.save(ROOT/'predictions'/(r['id']+'_comparison.jpg'),quality=95)
  records.append(dict(id=r['id'],split=r['split'],input='references/'+r['id']+'_input.png',reference='references/'+r['id']+'_overlay.png',predictions=probs,changes='predictions/'+r['id']+'_changes.png',scores=row['scores'],previous_omissions=int(dropped.sum()),found=int(found.sum()),remaining=int(remaining.sum()),new_omissions=int(extra.sum())))
 # Magnify recovered positions without drawing a connection or hiding misses.
 h=next(r for r in ds['records'] if r['id']=='H_14');z=np.load(h['path']);im=Image.fromarray(z['image']);prior=np.load(ROOT/'predictions/H_14_previous_refiner.npz')['prediction'];new=np.load(ROOT/'predictions/H_14_known_ink_retention.npz')['prediction'];boxes=[(105,155,140,185),(100,195,126,224),(185,185,220,215)]
 zoom=Image.new('RGB',(1200,720),'#f4f1e8');d=ImageDraw.Draw(zoom)
 for i,box in enumerate(boxes):
  for j,(a,title) in enumerate([(im,'原图像素局部'),(Image.fromarray(col[prior]),'上一轮范围'),(Image.fromarray(col[new]),'本轮范围')]):
   a=a.crop(box).resize(((box[2]-box[0])*5,(box[3]-box[1])*5),Image.Resampling.NEAREST);zoom.paste(a,(j*400+8,i*240+35));d.text((j*400+8,i*240+5),title,font=font(19),fill='#243e32')
 zoom.save(ROOT/'recovery_zoom.jpg',quality=95);(ROOT/'report_data.json').write_text(json.dumps(dict(records=records,diagnostic=result['diagnostic'],audit=read(ROOT/'retention_audit.json'),uncertain_queue=read(ROOT/'uncertain_reference_queue.json')),ensure_ascii=False,indent=2),encoding='utf8')
 # Retention loss is restricted to reviewed positive cores, not teacher pseudo-labels.
 x=torch.tensor([[[.2,.2,.2,.9]]],requires_grad=True);oldp=torch.full_like(x,.8);target=torch.tensor([[[2,0,255,1]]]);loss=retain_loss(x,oldp,target);loss.backward();assert x.grad[0,0,0]<0 and torch.count_nonzero(x.grad[0,0,1:])==0
 # Conditional roles remain comparable even at tiny nonzero foreground mass.
 a=torch.tensor([[[[.999999]],[[1e-7]],[[9e-7]]]]);b=torch.tensor([[[[1.]],[[1e-13]],[[9e-13]]]]);assert conditional_role_check(a,b)['max_error']<1e-6
 policy=read(LAB/'cunfa_role_reference_20261112/legacy_policy_audit.json');assert sha(LAB/'cunfa_fresh_validation_20261111/test_manifest.json')==policy['legacy_manifest_sha256']
 checks=dict(old_reference_hashes_unchanged=True,teacher_and_previous_refiner_unchanged=True,training_and_evaluation_weights_frozen=True,train_diagnostic_source_groups_disjoint=True,retention_loss_only_reviewed_positive_cores=True,unknown_and_paper_no_retention_gradient=True,low_foreground_conditional_check_passed=True,conditional_roles_unchanged=True,evaluation_resumed_without_retraining=True,old_13_test_manifest_unchanged=True,repeated_local_diagnostic_not_blind=True,new_verified_crossing_or_endpoint_labels=0,model_adopted=False,robot_connected=False);(ROOT/'verification.json').write_text(json.dumps(checks,ensure_ascii=False,indent=2),encoding='utf8')
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>淡线保留约束 · 原始输出与遗漏复核</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f1e8;color:#243e32;font:16px/1.65 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1440px;padding:28px;margin:auto}h1{font-size:30px;line-height:1.35}h2{font-size:23px;margin-top:32px}.note{padding:16px;background:#fff9e8;border-left:5px solid #b57c3c}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.card{padding:12px;border:1px solid #d7d9c9;border-radius:8px;background:#fffdf7}img{max-width:100%;height:auto;display:block;max-height:460px;margin:auto}select{font:inherit;padding:8px;max-width:100%;border:1px solid #a2b1a5;background:#fffdf7;border-radius:6px}.controls{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin:14px 0}table{border-collapse:collapse;width:100%}td,th{padding:10px;text-align:left;border-bottom:1px solid #d6d9c9}.scroll{overflow:auto}.warn{color:#8f4b32}small{color:#647468}a{color:#236b61}@media(max-width:650px){main{padding:15px}.grid{grid-template-columns:1fr}h1{font-size:25px}td,th{padding:6px;font-size:13px}}</style><main><small>2026-11-12 · 离线实验 · 未连接机械臂</small><h1>收窄墨带时，增加对已有淡墨的保留约束</h1><p class="note"><b>同一复核局部中，找回了上一轮38个新增遗漏像素中的12个，仍有26个未找回，未新增遗漏。</b><br>这些是助手参考范围内的像素，不是12条完整笔画；诊断画面反复使用，不能称为独立盲测。当前不替换绘画版本。</p>
<h2>1. 先核对遗漏原因</h2><p>原有角色概率保持不变，丢失出现在墨迹前景被压成背景时。本轮没有重画参考或将模型预测改成标签。训练只在已有可靠程度有限的局部参考上增加保留约束，并加入对比度减弱增强；灰边、遮挡和未标区域继续忽略。</p><p>两组从相同上一轮范围模型开始，采用相同增强、固定240步和最后检查点；唯一训练损失差异为是否增加已有墨迹的保留约束。测试图的参考不参与梯度或参数选择。</p>
<h2>2. 原图、原始输出与剩余遗漏</h2><div class="controls"><label>观察 <select id="case"></select></label><span id="split"></span></div><div class="grid"><div class="card"><b>静态输入</b><img id="input"></div><div class="card"><b>上一轮范围修正</b><img id="previous"></div><div class="card"><b>本轮保留约束</b><img id="new"></div></div><p>橙=结构，蓝=皴笔。模型原始角色图未按原图阈值或参考遮罩二次裁剪，没有几何续接；仍不是完整笔触或机械臂轨迹。</p><div class="grid"><div class="card"><b>参考内变化标记</b><img id="changes"></div><div class="card"><b>之前核查的区间参考</b><img id="reference"></div><div class="card"><b>本观察统计</b><p id="counts"></p><p>绿=找回，红=仍遗漏，紫=新增遗漏。彩色变化仅用于评价展示，不输入模型。</p></div></div>
<h2>3. 相同步数对照</h2><div class="scroll"><table><thead><tr><th>方法</th><th>找回旧遗漏 / 38</th><th>新增遗漏</th><th>皴笔核心召回</th><th>近邻纸面误检</th></tr></thead><tbody id="metrics"></tbody></table></div><p>原始三分类皴笔核心召回为80.6%；上一轮范围修正为76.8%；本轮约束为78.0%，仍未恢复至原始水平。近邻纸面只核查了644个像素，0%不代表整幅没有误检。已有三段区间参考的确定墨迹保留仍为98.4%。</p><p class="warn">这些都是同一件作品同一局部的重复诊断，参考未经专家逐像素审核。画家身份未核实，也没有完整墨带、完整分笔或皴法类别的独立验证。</p>
<h2>4. 放大检查</h2><img src="recovery_zoom.jpg"><p>放大仅复用原生像素，未生成新图像信息。找回的多数是细笔迹或边缘少量像素，不能据此称为恢复了完整长笔触。</p>
<h2>5. 交叉、干笔与收笔参考仍不足</h2><img src="uncertain_events.jpg"><p>复核了已有S04交叉片段与S05提笔/重起片段：交叉处归属不明，微弱上段和提笔时间仍无法可靠确定，继续排除。<b>本轮没有新增经过确认的交叉分笔或收笔标签。</b>不能把断续一律接成一笔，或把图像尖端当作实机提笔位置。</p>
<h2>6. 下一步验收门槛</h2><ol><li>扩大高分辨率、可核对原作者的完整局部参考，尤其是26个剩余遗漏附近的真实淡墨与纸纹区分。</li><li>在预先封存的新作品上同时验证：主轮廓、皴笔完整性、墨带间距和新增杂线，避免只针对这张图调好。</li><li>角色与墨带稳定后，再训练真实分笔归属、曲线、笔组和对象内顺序。本轮没有提供皴法理解、创作或机械臂执行的新证据。</li></ol><p><a href="protocol.json">固定训练协议</a> · <a href="retention_audit.json">逐处遗漏核查</a> · <a href="results.json">逐例结果</a> · <a href="uncertain_reference_queue.json">待定参考</a> · <a href="verification.json">检查记录</a></p></main><script>let D;const $=s=>document.getElementById(s),pct=v=>(v*100).toFixed(1)+'%';function show(){let r=D.records[$('case').selectedIndex];$('input').src=r.input;$('previous').src=r.predictions.previous_refiner;$('new').src=r.predictions.known_ink_retention;$('changes').src=r.changes;$('reference').src=r.reference;$('split').textContent=r.split==='train'?'开发训练观察':'重复复核局部，非盲测';$('counts').textContent='原有新增遗漏 '+r.previous_omissions+'，找回 '+r.found+'，剩余 '+r.remaining+'，新增遗漏 '+r.new_omissions;}fetch('report_data.json').then(r=>r.json()).then(d=>{D=d;for(let r of D.records){let o=document.createElement('option');o.textContent=r.id;$('case').append(o)}$('case').selectedIndex=4;$('case').onchange=show;show();let s=D.diagnostic.scores;for(let [k,n] of [['previous_refiner','上一轮范围修正'],['matched_continuation','同预算普通续训'],['known_ink_retention','同预算增加保留约束']]){let r=s[k],tr=document.createElement('tr');tr.innerHTML='<td>'+n+'</td><td>'+r.recovered_previous_suppression+'</td><td>'+r.newly_suppressed_vs_previous+'</td><td>'+pct(r.core_roles.recall[2])+'</td><td>'+pct(r.band_ink.near_paper_false_ink)+'</td>';$('metrics').append(tr)}window.reportReady=true});</script></html>'''
 correction_notice=LAB/'cunfa_object_correction_20261112/notice.html'
 if correction_notice.exists():page=page.replace('<h2>1. 先核对遗漏原因</h2>',correction_notice.read_text('utf8')+'<h2>1. 先核对遗漏原因</h2>')
 (ROOT/'index.html').write_text(page,encoding='utf8');print(json.dumps(checks,ensure_ascii=False),flush=True)
if __name__=='__main__':main()
